# Analyze the distribution of values across regions
from collections import Counter

region_items = {}
for r_idx, (r1, r2) in enumerate([(0,4), (6,10), (12,16), (18,22), (24,28)]):
    for c_idx, (c1, c2) in enumerate([(0,3), (5,8), (10,13), (15,18), (20,23)]):
        val_counts = []
        for r in range(r1, r2+1):
            for c in range(c1, c2+1):
                if grid[r][c] not in [0, 5]:
                    val_counts.append(grid[r][c])
        if val_counts:
            cnt = Counter(val_counts)
            region_items[(r_idx, c_idx)] = {
                'counts': dict(cnt),
                'total': len(val_counts)
            }

print("Value counts per region:")
for k, v in sorted(region_items.items()):
    print(f"{k}: {v['counts']}")

# Calculate relative positions within each region
region_rows = [(0,4), (6,10), (12,16), (18,22), (24,28)]
region_cols = [(0,3), (5,8), (10,13), (15,18), (20,23)]

