def create_value_pos_output():
    # Define mapping from value to position
    # Using value to determine which "slot" in the region
    value_to_pos = {
        1: (0, 0),   # top-left
        2: (1, 1),   # near-center
        3: (2, 2),   # center-right  
        4: (3, 3),   # bottom-right
    }

    height = len(grid)
    width = len(grid[0])
    output = [[5]*width for _ in range(height)]

    rows_sep = [5, 11, 17, 23]
    cols_sep = [4, 9, 14, 19]
    for r in rows_sep:
        output[r] = [0]*width
    for c in cols_sep:
        for r in range(height):
            output[r][c] = 0

    region_rows = [(0,4), (6,10), (12,16), (18,22), (24,28)]
    region_cols = [(0,3), (5,8), (10,13), (15,18), (20,23)]

    for r_idx, (r1, r2) in enumerate(region_rows):
        for c_idx, (c1, c2) in enumerate(region_cols):
            for r in range(r1, r2+1):
                for c in range(c1, c2+1):
                    val = grid[r][c]
                    if val not in [0, 5]:
                        rel_r, rel_c = value_to_pos[val]
                        # Place at absolute position
                        out_r = r1 + rel_r
                        out_c = c1 + rel_c
                        output[out_r][out_c] = val

    return output

